#include "stdafx.h"#include "HcdElementBase.h"struct SOR_P{#include "PrivateVars/OR.h"};class KOR : public KHcdElementBase  , protected SOR_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _OR("OR", KOR::Create);IHcdElement *KOR::Create(){  return new KOR;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KOR, 17 )void KOR::InitParm(){#include "PrivateVars/OR.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KOR::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KOR::StepCalc( SStepCalcParams &params ){  tBool *pInvert = &II1;  tBool *pIn = &INL0;  if( pInvert[0] )    OUTR0 = pIn[0] ? 0 : 1;  else    OUTR0 = pIn[0] ? 1 : 0;  for( int i=1; i<8; ++i )  {    if( pInvert[i] )      OUTR0 = (pIn[i] ? 0 : 1) | OUTR0;    else      OUTR0 = (pIn[i] ? 1 : 0) | OUTR0;    if( OUTR0 )      break;  }}